CREATE TABLE "RecommendationOutcome" ("id" TEXT NOT NULL,"agencyId" TEXT NOT NULL,"userId" TEXT NOT NULL,"applicantId" TEXT NOT NULL,"actionKey" TEXT NOT NULL,"executedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"baselineStage" TEXT NOT NULL,"outcome" TEXT,"outcomeAt" TIMESTAMP(3),"success" BOOLEAN,"metadata" JSONB DEFAULT '{}',CONSTRAINT "RecommendationOutcome_pkey" PRIMARY KEY ("id"));CREATE INDEX "RecommendationOutcome_agencyId_actionKey_executedAt_idx" ON "RecommendationOutcome"("agencyId","actionKey","executedAt");CREATE INDEX "RecommendationOutcome_applicantId_executedAt_idx" ON "RecommendationOutcome"("applicantId","executedAt");